/* ===================== INST·01 — MAPA DA FATURA, TRÊS LENTES ===================== */
(function(){
  var grid=$id('mf-grid'), lens=$id('mf-lens'), line=$id('mf-line');
  if(!grid||!lens||!line)return;

  var LENTE=/* LENTE: literal elidido, ver dados_do_script.LENTE (L3611–3618) */;

  var LINHAS=/* LINHAS: literal elidido, ver dados_do_script.LINHAS (L3620–3677) */;

  var lente='unit', sel=null;

  function render(){
    lens.innerHTML='<div class="yr">Lente ativa</div><div class="ti">'+LENTE[lente].t+
      '</div><div class="bd2">'+LENTE[lente].d+'</div>';
    grid.innerHTML=LINHAS.map(function(l){
      return '<button class="tr-chip'+(sel===l.id?' on':'')+'" data-k="'+l.id+'">'+
        '<span class="y">'+esc(l.c)+'</span>'+esc(l.n)+'</button>';
    }).join('');
    $all('button',grid).forEach(function(b){
      b.addEventListener('click',function(){sel=b.getAttribute('data-k');render();});
    });
    if(!sel){
      line.innerHTML='<div class="yr">Detalhe</div><div class="ti">Escolha uma linha</div>'+
        '<div class="bd2">Catorze famílias de componentes. A lente ativa determina a pergunta feita a cada uma delas.</div>';
      return;
    }
    var L=null;
    for(var i=0;i<LINHAS.length;i++){if(LINHAS[i].id===sel)L=LINHAS[i];}
    if(!L)return;
    line.innerHTML='<div class="yr">'+esc(L.c)+' · '+LENTE[lente].t+'</div>'+
      '<div class="ti">'+esc(L.n)+'</div><div class="bd2">'+L[lente]+'</div>'+
      '<div class="lg"><b>As outras duas lentes</b>'+
      Object.keys(LENTE).filter(function(k){return k!==lente;}).map(function(k){
        return '<b style="display:inline;font-size:11px;letter-spacing:0;text-transform:none;color:var(--txt-3)">'+
          LENTE[k].t+':</b> '+L[k].replace(/<[^>]+>/g,'')+'<br>';
      }).join('')+'</div>';
  }

  segBind('mf-seg',function(b){lente=b.getAttribute('data-l');render();});
  render();
})();

/* ===================== INST·02 — COMPARADOR DE MODALIDADES ===================== */
(function(){
  var vd=$id('cm-vd'), out=$id('cm-out');
  if(!vd||!out)return;

  var PERFIL=/* PERFIL: literal elidido, ver dados_do_script.PERFIL (L3717–3723) */;

  var ELEG=/* ELEG: literal elidido, ver dados_do_script.ELEG (L3725–3725) */;
  var SGNOME=/* SGNOME: literal elidido, ver dados_do_script.SGNOME (L3726–3726) */;

  var CEL=/* CEL: literal elidido, ver dados_do_script.CEL (L3728–3789) */;

  function render(){
    var p=segVal('cm-perf','data-p')||'plana';
    var m=segVal('cm-mod','data-m')||'azul';
    var s=segVal('cm-sg','data-s')||'a4';
    var cel=CEL[m+'|'+p];
    var elegivel=(ELEG[s].indexOf(m)>=0);

    var cls, head;
    if(m==='conv'){
      cls='per';
      head='<b>Não é opção ordinária de enquadramento.</b> A modalidade convencional binômia não figura na relação vigente de modalidades disponíveis ao grupo A. Subsiste como estrutura no arcabouço metodológico tarifário e em situações contratuais específicas, e por isso não entra na comparação entre alternativas contratáveis.';
    } else if(!elegivel){
      cls='per';
      head='<b>Modalidade indisponível ao subgrupo '+SGNOME[s]+'.</b> A modalidade de demanda única é disponível apenas aos subgrupos A3a, A4 e AS. Simular esta modalidade para o subgrupo '+SGNOME[s]+' é erro de elegibilidade, não de premissa — e é verificável no cadastro da própria fatura antes de qualquer cálculo.';
    } else {
      cls='ok';
      head='<b>Modalidade elegível ao subgrupo '+SGNOME[s]+'.</b> Perfil considerado: '+PERFIL[p]+'. As direções abaixo são estruturais e derivam da forma de cobrança; a magnitude depende das tarifas homologadas da concessionária e do perfil medido real.';
    }

    vd.className='verdict '+cls;
    vd.innerHTML=head;

    out.innerHTML=
      '<div class="ocard"><span class="ok2">Direção estrutural</span>'+esc(cel.dir)+'</div>'+
      '<div class="ocard"><span class="ok2">Linhas que mudariam</span>'+esc(cel.linhas)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">Risco dominante</span>'+esc(cel.risco)+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que falta para concluir</span>'+esc(cel.falta)+'</div>'+
      '<div class="ocard"><span class="ok2">O que este instrumento não devolve</span>Valor de economia, percentual de redução ou qualquer conclusão financeira. Sem doze meses de medição e sem as tarifas homologadas da concessionária específica, qualquer número seria estimativa apresentada como resultado.</div>';
  }

  segBind('cm-perf',render);
  segBind('cm-mod',render);
  segBind('cm-sg',render);
  render();
})();

/* ===================== INST·03 — DIMENSIONADOR DE DEMANDA ===================== */
(function(){
  if(!$id('dd-vd'))return;

  var FAIXA=/* FAIXA: literal elidido, ver dados_do_script.FAIXA (L3831–3857) */;

  function calc(){
    var ctr=numOf($id('dd-ctr'),1200,10,20000);
    var max=numOf($id('dd-max'),1010,10,20000);
    var med=numOf($id('dd-med'),720,1,20000);
    var mes=numOf($id('dd-mes'),12,1,36);
    var tol=numOf($id('dd-tol'),5,0,20);

    var util=ctr>0?(max/ctr*100):0;
    var fc=max>0?(med/max*100):0;
    var lim=ctr*(1+tol/100);
    var folga=lim-max;

    $id('dd-util').textContent=fmt(util,1)+'%';
    $id('dd-fc').textContent=fmt(fc,1)+'%';
    $id('dd-lim').textContent=fmt(lim,0)+' kW';
    $id('dd-folga').textContent=fmt(folga,0)+' kW';

    var F=FAIXA[FAIXA.length-1];
    for(var i=0;i<FAIXA.length;i++){if(util<=FAIXA[i].max){F=FAIXA[i];break;}}

    var vd=$id('dd-vd');
    vd.className='verdict '+F.cls;
    var histNota='';
    if(mes<6){
      histNota=' <b>Atenção ao histórico:</b> com '+fmt(mes,0)+' mes'+(mes===1?'':'es')+
        ' de série, nenhum diagnóstico de dimensionamento é concluível. A faixa acima descreve o que se vê, não o que se pode afirmar.';
    } else if(mes<12){
      histNota=' <b>Histórico parcial:</b> '+fmt(mes,0)+' meses não cobrem um ciclo anual completo. Sazonalidade, parada programada e retomada após interrupção podem estar fora da janela observada.';
    }
    vd.innerHTML='<b>'+F.t+'.</b> Utilização do contrato em '+fmt(util,1)+
      '%, com fator de carga aparente de '+fmt(fc,1)+'%.'+histNota;

    var zona='';
    if(util>80&&util<=95&&mes>=12){
      zona='<div class="ocard gd2"><span class="ok2">Zona de decisão de risco</span>Esta é a faixa em que a resposta correta frequentemente é <b>depende do plano de produção</b>. A série histórica sozinha não distingue um contrato bem calibrado de um contrato que ficará apertado com a expansão do ano seguinte. Sem o plano, o instrumento descreve; ele não recomenda.</div>';
    }
    if(mes<12){
      zona='<div class="ocard rd2"><span class="ok2">Não é possível concluir</span>Com menos de doze meses, a distinção entre folga estrutural e mês atípico não é possível. Em muitas operações industriais, o mês atípico é justamente o que define o contrato — retomada após interrupção, teste de carga, coincidência de partidas. A saída correta aqui é a lista do que falta, não um número recomendado.</div>';
    }

    $id('dd-out').innerHTML=
      '<div class="ocard"><span class="ok2">O que este resultado significa</span>'+esc(F.sig)+'</div>'+
      '<div class="ocard"><span class="ok2">O que costuma causá-lo</span>'+esc(F.causa)+'</div>'+
      '<div class="ocard"><span class="ok2">O que a empresa controla</span>'+esc(F.ctrl)+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que ainda falta saber</span>'+esc(F.falta)+'</div>'+zona;
  }

  ['ctr','max','med','mes','tol'].forEach(function(k){pair('dd-'+k,'dd-'+k+'r',calc);});
  calc();
})();

/* ===================== INST·04 — SIMULADOR DE ULTRAPASSAGEM ===================== */
(function(){
  if(!$id('ul-vd'))return;

  var FAIXA=/* FAIXA: literal elidido, ver dados_do_script.FAIXA (L3914–3935) */;

  function calc(){
    var ctr=numOf($id('ul-ctr'),1000,10,20000);
    var med=numOf($id('ul-med'),1060,10,20000);
    var tol=numOf($id('ul-tol'),5,0,20);
    var mul=numOf($id('ul-mul'),2,1,4);
    var tar=numOf($id('ul-tar'),40,1,300);

    var lim=ctr*(1+tol/100);
    var disparou=med>lim;
    var base=disparou?(med-ctr):0;
    var normal=ctr*tar;
    var pen=base*mul*tar;
    var total=normal+pen;
    var peso=total>0?(pen/total*100):0;
    var exc=ctr>0?((med/ctr-1)*100):0;

    $id('ul-lim').textContent=fmt(lim,0)+' kW';
    $id('ul-base').textContent=fmt(base,0)+' kW';
    $id('ul-norm').textContent=fmt(normal,0);
    $id('ul-pen').textContent=fmt(pen,0);
    $id('ul-peso').textContent=fmt(peso,1)+'%';

    var F=FAIXA[FAIXA.length-1];
    for(var i=0;i<FAIXA.length;i++){
      var chave = disparou ? exc : (lim>0?(lim-med)/ctr*100*-1:0);
      if(!disparou){
        var margem=(lim-med)/ctr*100;
        if(margem>2){F=FAIXA[0];}else{F=FAIXA[1];}
        break;
      } else {
        if(exc<=15){F=FAIXA[2];}else{F=FAIXA[3];}
        break;
      }
    }

    var vd=$id('ul-vd');
    vd.className='verdict '+F.cls;
    if(disparou){
      vd.innerHTML='<b>'+F.t+'.</b> A medição de '+fmt(med,0)+' kW superou o limite de disparo de '+
        fmt(lim,0)+' kW. A base da parcela é <b>'+fmt(base,0)+' kW</b> — a diferença entre medida e contratada, e não os '+
        fmt(med-lim,0)+' kW acima da tolerância. Essa é a distinção que material comercial mais frequentemente inverte.';
    } else {
      vd.innerHTML='<b>'+F.t+'.</b> A medição de '+fmt(med,0)+' kW ficou abaixo do limite de disparo de '+
        fmt(lim,0)+' kW. Nenhuma parcela de ultrapassagem é gerada neste ciclo. Margem disponível: '+
        fmt(lim-med,0)+' kW.';
    }

    $id('ul-out').innerHTML=
      '<div class="ocard"><span class="ok2">O que este resultado significa</span>'+esc(F.sig)+'</div>'+
      '<div class="ocard"><span class="ok2">O que costuma causá-lo</span>'+esc(F.causa)+'</div>'+
      '<div class="ocard"><span class="ok2">O que a empresa controla</span>'+esc(F.ctrl)+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que ainda falta saber</span>'+esc(F.falta)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">Parâmetros que você precisa confirmar</span>Tolerância e multiplicador são parâmetros normativos e vêm aqui como entrada editável por decisão de projeto. A tolerância difere conforme a natureza da demanda contratada, e há material em circulação reproduzindo multiplicador de redação anterior à consolidação de 2021. Confirme no texto compilado vigente e no contrato de uso da unidade antes de qualquer uso externo.</div>';
  }

  ['ctr','med','tol','mul','tar'].forEach(function(k){pair('ul-'+k,'ul-'+k+'r',calc);});
  calc();
})();

/* ===================== INST·05 — DESLOCADOR DE CARGA ENTRE POSTOS ===================== */
(function(){
  if(!$id('dl-vd'))return;

  var FAIXA=/* FAIXA: literal elidido, ver dados_do_script.FAIXA (L4000–4021) */;

  function calc(){
    var tot=numOf($id('dl-tot'),420,1,20000);
    var pta=numOf($id('dl-pta'),42,0,20000);
    var des=numOf($id('dl-des'),30,0,100);
    var hrs=numOf($id('dl-hrs'),63,1,200);

    if(pta>tot){pta=tot;$id('dl-pta').value=pta;$id('dl-ptar').value=pta;}

    var p0=tot>0?(pta/tot*100):0;
    var vol=pta*des/100;
    var pta1=pta-vol;
    var p1=tot>0?(pta1/tot*100):0;
    var pot=hrs>0?(pta*1000/hrs):0;

    $id('dl-p0').textContent=fmt(p0,1)+'%';
    $id('dl-p1').textContent=fmt(p1,1)+'%';
    $id('dl-vol').textContent=fmt(vol,1)+' MWh';
    $id('dl-pot').textContent=fmt(pot,0)+' kW';

    $id('dl-bars').innerHTML=
      '<div class="bar-row"><span class="lb">Ponta hoje</span><span class="bar-track">'+
      '<span class="bar-fill" style="width:'+clamp(p0*3,0,100)+'%;background:var(--rd)"></span></span>'+
      '<span class="vl">'+fmt(pta,1)+' MWh</span></div>'+
      '<div class="bar-row"><span class="lb">Ponta depois</span><span class="bar-track">'+
      '<span class="bar-fill" style="width:'+clamp(p1*3,0,100)+'%;background:var(--gd)"></span></span>'+
      '<span class="vl">'+fmt(pta1,1)+' MWh</span></div>'+
      '<div class="bar-row"><span class="lb">Fora de ponta</span><span class="bar-track">'+
      '<span class="bar-fill" style="width:'+clamp((tot-pta1)/tot*100,0,100)+'%;background:var(--gr)"></span></span>'+
      '<span class="vl">'+fmt(tot-pta1,1)+' MWh</span></div>';

    var F=FAIXA[FAIXA.length-1];
    for(var i=0;i<FAIXA.length;i++){if(p0<=FAIXA[i].max){F=FAIXA[i];break;}}

    var vd=$id('dl-vd');
    vd.className='verdict '+F.cls;
    vd.innerHTML='<b>'+F.t+'.</b> A ponta representa '+fmt(p0,1)+
      '% do consumo do ciclo. Deslocando '+fmt(des,0)+'% desse volume, a participação cairia para '+
      fmt(p1,1)+'%, com <b>'+fmt(vol,1)+' MWh</b> transferidos para fora da janela. '+
      'A potência média demandada dentro da janela é de aproximadamente '+fmt(pot,0)+
      ' kW — número que não deve ser confundido com a demanda máxima registrada no posto.';

    $id('dl-out').innerHTML=
      '<div class="ocard"><span class="ok2">O que este resultado significa</span>'+esc(F.sig)+'</div>'+
      '<div class="ocard"><span class="ok2">O que costuma causá-lo</span>'+esc(F.causa)+'</div>'+
      '<div class="ocard"><span class="ok2">O que a empresa controla</span>'+esc(F.ctrl)+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que ainda falta saber</span>'+esc(F.falta)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">Por que não há valor em dinheiro aqui</span>Converter volume deslocado em valor exigiria a diferença entre as tarifas de energia dos dois postos na concessionária específica, e, na modalidade que separa demanda por posto, também o efeito sobre a demanda de ponta. Nenhuma dessas informações está na fatura sozinha. O volume é o que o instrumento pode afirmar; o valor é o que o processo tarifário determina.</div>';
  }

  ['tot','pta','des','hrs'].forEach(function(k){pair('dl-'+k,'dl-'+k+'r',calc);});
  calc();
})();

/* ===================== INST·06 — APURADOR DE EXCEDENTE REATIVO ===================== */
(function(){
  if(!$id('fp-vdt'))return;

  var FAIXA=/* FAIXA: literal elidido, ver dados_do_script.FAIXA (L4080–4106) */;

  function calc(){
    var ref=numOf($id('fp-ref'),0.92,0.5,1);
    var ind=numOf($id('fp-ind'),0.87,0.3,1);
    var cap=numOf($id('fp-cap'),0.95,0.3,1);
    var vdi=numOf($id('fp-vd1'),180,0,600);
    var vno=numOf($id('fp-vn1'),0,0,200);
    var hrs=numOf($id('fp-hrs'),6,1,10);

    var totNoite=hrs*30;
    var totDia=(24-hrs)*30;
    if(vdi>totDia){vdi=Math.round(totDia);$id('fp-vd1').value=vdi;$id('fp-vd1r').value=vdi;}
    if(vno>totNoite){vno=Math.round(totNoite);$id('fp-vn1').value=vno;$id('fp-vn1r').value=vno;}

    var pd=totDia>0?(vdi/totDia*100):0;
    var pn=totNoite>0?(vno/totNoite*100):0;
    var dd=ref-ind;
    var dn=ref-cap;

    $id('fp-pd').textContent=fmt(pd,1)+'%';
    $id('fp-pn').textContent=fmt(pn,1)+'%';
    $id('fp-dd').textContent=(dd>0?'−':'+')+fmt(Math.abs(dd),3);
    $id('fp-dn').textContent=(dn>0?'−':'+')+fmt(Math.abs(dn),3);

    var temInd=(vdi>0&&ind<ref);
    var temCap=(vno>0&&cap<ref);
    var key='limpo';
    if(temInd&&temCap){key='ambas';}
    else if(temCap){key='cap';}
    else if(temInd){key=(pd>25)?'ind-estr':'ind-pont';}

    var F=FAIXA[0];
    for(var i=0;i<FAIXA.length;i++){if(FAIXA[i].k===key)F=FAIXA[i];}

    var vd=$id('fp-vdt');
    vd.className='verdict '+F.cls;
    var nota='';
    if(vdi>0&&ind>=ref){
      nota=' <b>Inconsistência de entrada:</b> foram informados intervalos em violação na janela indutiva, mas o fator típico informado está dentro da referência. Verifique se a violação ocorre em intervalos específicos que a média não representa — o que é comum e é justamente por isso que a apuração é por intervalo.';
    }
    if(vno>0&&cap>=ref){
      nota+=' <b>Inconsistência de entrada:</b> foram informados intervalos em violação na janela capacitiva com fator típico dentro da referência. O mesmo raciocínio se aplica: a média mensal esconde violação por intervalo.';
    }
    vd.innerHTML='<b>'+F.t+'.</b> '+fmt(pd,1)+'% dos intervalos da janela indutiva e '+
      fmt(pn,1)+'% dos intervalos da janela capacitiva foram informados como em violação, considerando janela noturna de '+
      fmt(hrs,0)+' horas e referência de '+fmt(ref,2)+'.'+nota;

    $id('fp-out').innerHTML=
      '<div class="ocard"><span class="ok2">O que este resultado significa</span>'+esc(F.sig)+'</div>'+
      '<div class="ocard"><span class="ok2">O que costuma causá-lo</span>'+esc(F.causa)+'</div>'+
      '<div class="ocard"><span class="ok2">O que a empresa controla</span>'+esc(F.ctrl)+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que ainda falta saber</span>'+esc(F.falta)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">Onde a fatura para de servir</span>A fatura prova que houve cobrança; ela não prova qual banco instalar, em que ponto, com quantos estágios nem com que proteção. Entre o achado e a solução existe um estudo elétrico com medição de qualidade de energia, inventário de cargas e verificação de risco de ressonância, conduzido por profissional habilitado. Este instrumento caracteriza o problema — ele não dimensiona a solução.</div>';
  }

  ['ref','ind','cap','hrs'].forEach(function(k){pair('fp-'+k,'fp-'+k+'r',calc);});
  pair('fp-vd1','fp-vd1r',calc);
  pair('fp-vn1','fp-vn1r',calc);
  calc();
})();

/* ===================== INST·07 — ANATOMIA DOS ENCARGOS ===================== */
(function(){
  var grid=$id('en-grid'), panel=$id('en-panel');
  if(!grid||!panel)return;

  var ENC=/* ENC: literal elidido, ver dados_do_script.ENC (L4173–4229) */;

  var sel=null;

  function render(){
    grid.innerHTML=ENC.map(function(e){
      return '<button class="tr-chip'+(sel===e.id?' on':'')+'" data-k="'+e.id+'">'+
        '<span class="y">'+esc(e.tag)+'</span>'+esc(e.n)+'</button>';
    }).join('');
    $all('button',grid).forEach(function(b){
      b.addEventListener('click',function(){sel=b.getAttribute('data-k');render();});
    });
    if(!sel){
      panel.innerHTML='<div class="yr">Anatomia</div><div class="ti">Escolha um item</div>'+
        '<div class="bd2">Onze itens da linha de encargos e obrigações setoriais, cada um com quatro campos fixos. Ler o mesmo campo em todos os onze, na vertical, ensina mais do que ler um item inteiro.</div>';
      return;
    }
    var E=null;
    for(var i=0;i<ENC.length;i++){if(ENC[i].id===sel)E=ENC[i];}
    if(!E)return;
    panel.innerHTML='<div class="yr">'+esc(E.tag)+'</div><div class="ti">'+esc(E.n)+'</div>'+
      '<div class="out" style="margin-top:6px">'+
      '<div class="ocard"><span class="ok2">O que financia</span>'+esc(E.fin)+'</div>'+
      '<div class="ocard"><span class="ok2">Quem paga</span>'+esc(E.paga)+'</div>'+
      '<div class="ocard"><span class="ok2">Como aparece na fatura</span>'+esc(E.fat)+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que mudou ou pode mudar</span>'+E.mud+'</div>'+
      '</div>';
  }
  render();
})();

/* ===================== INST·08 — RÉGUA DO CICLO TARIFÁRIO ===================== */
(function(){
  var grid=$id('rc-grid'), panel=$id('rc-panel');
  if(!grid||!panel)return;

  var ET=/* ET: literal elidido, ver dados_do_script.ET (L4265–4306) */;

  var sel=null, marc={};

  function render(){
    grid.innerHTML=ET.map(function(e){
      return '<button class="tr-chip'+(sel===e.id?' on':'')+'" data-k="'+e.id+'">'+
        '<span class="y">'+esc(e.et)+(marc[e.id]?' · verificada':'')+'</span>'+esc(e.n)+'</button>';
    }).join('');
    $all('button',grid).forEach(function(b){
      b.addEventListener('click',function(){
        var k=b.getAttribute('data-k');
        if(sel===k){marc[k]=!marc[k];}else{sel=k;}
        render();
      });
    });

    var n=0;
    for(var k in marc){if(marc[k])n++;}
    $id('rc-cnt').textContent=fmt(n,0)+' de '+ET.length;

    var est,cls;
    if(n===0){est='Dossiê não iniciado';cls='per';}
    else if(n<4){est='Dossiê parcial';cls='per';}
    else if(n<8){est='Dossiê em construção';cls='att';}
    else {est='Dossiê completo';cls='ok';}
    $id('rc-est').textContent=est;

    var vd=$id('rc-vd');
    vd.className='verdict '+cls;
    if(n===0){
      vd.innerHTML='<b>Nenhuma etapa verificada.</b> Sem o dossiê do ciclo tarifário da concessionária, qualquer comparação entre dois períodos atribui a decisões da empresa efeitos que podem ter sido do calendário. Clique numa etapa para ler o detalhe; clique de novo na etapa já selecionada para marcá-la como verificada.';
    } else if(n<4){
      vd.innerHTML='<b>Dossiê parcial — '+fmt(n,0)+' de '+ET.length+'.</b> Ainda não é possível decompor variação entre efeito preço e efeito quantidade com segurança. As etapas de estrutura, homologação e aplicação são as que mais frequentemente explicam variação inesperada.';
    } else if(n<8){
      vd.innerHTML='<b>Dossiê em construção — '+fmt(n,0)+' de '+ET.length+'.</b> Já há base para explicar parte da variação. Verifique especialmente se a etapa de definição de estrutura foi coberta: é nela que o intervalo de ponta pode ter mudado, e essa mudança invalida silenciosamente qualquer simulação de deslocamento.';
    } else {
      vd.innerHTML='<b>Dossiê completo.</b> Com as oito etapas verificadas, uma comparação de doze meses pode declarar o que mudou no meio, componente a componente. Este é o estado mínimo para que um relatório atribua corretamente cada parcela de variação a preço, a quantidade ou a calendário.';
    }

    if(!sel){
      panel.innerHTML='<div class="yr">Régua</div><div class="ti">Escolha uma etapa</div>'+
        '<div class="bd2">Do início do processo tarifário até o efeito na fatura. Clicar numa etapa abre o detalhe; clicar novamente na etapa aberta alterna a marcação de verificada.</div>';
      return;
    }
    var E=null;
    for(var i=0;i<ET.length;i++){if(ET[i].id===sel)E=ET[i];}
    if(!E)return;
    panel.innerHTML='<div class="yr">'+esc(E.et)+(marc[E.id]?' · verificada':'')+'</div>'+
      '<div class="ti">'+esc(E.n)+'</div>'+
      '<div class="out" style="margin-top:6px">'+
      '<div class="ocard"><span class="ok2">O que acontece</span>'+esc(E.oq)+'</div>'+
      '<div class="ocard"><span class="ok2">Quem decide</span>'+esc(E.quem)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">O que pode surpreender</span>'+E.surp+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que arquivar</span>'+esc(E.arq)+'</div>'+
      '</div>';
  }
  render();
})();

/* ===================== INST·09 — RECONSTRUTOR DE FATURA ===================== */
(function(){
  if(!$id('rb-vd'))return;

  var NOMES=/* NOMES: literal elidido, ver dados_do_script.NOMES (L4370–4370) */;

  var DIAG=/* DIAG: literal elidido, ver dados_do_script.DIAG (L4372–4398) */;

  function calc(){
    var est=[],real=[];
    for(var i=1;i<=6;i++){
      est.push(numOf($id('rb-e'+i),0,0,100));
      real.push(numOf($id('rb-r'+i),0,0,100));
    }
    var se=0,sr=0;
    for(var j=0;j<6;j++){se+=est[j];sr+=real[j];}

    var errTot=0, maiorV=0, maiorI=0;
    var rows='';
    for(var k=0;k<6;k++){
      var d=est[k]-real[k];
      errTot+=Math.abs(d);
      if(Math.abs(d)>Math.abs(maiorV)){maiorV=d;maiorI=k;}
      var w=clamp(Math.abs(d)*4,0,50);
      var cls=d>0?'over':(d<0?'under':'');
      var left=d>=0?50:(50-w);
      rows+='<div class="err-row"><span class="err-nm">'+esc(NOMES[k])+'</span>'+
        '<span class="err-bar"><span class="err-mid"></span>'+
        '<span class="err-fill '+cls+'" style="left:'+left+'%;width:'+w+'%"></span></span>'+
        '<span class="err-v'+(Math.abs(d)>=8?' big':'')+'">'+(d>0?'+':'')+fmt(d,0)+' p.p.</span></div>';
    }

    $id('rb-se').textContent=fmt(se,0)+'%';
    $id('rb-sr').textContent=fmt(sr,0)+'%';
    $id('rb-err').textContent=fmt(errTot,0)+' p.p.';
    $id('rb-maior').textContent=NOMES[maiorI]+' · '+(maiorV>0?'+':'')+fmt(maiorV,0);
    $id('rb-rows').innerHTML=rows;

    var key='equilibrado';
    if(Math.abs(maiorV)>=6){
      if(maiorI===0&&maiorV>0){key='energia';}
      else if(maiorI===2&&maiorV<0){key='demanda';}
      else if(maiorI===1){key='rede';}
      else if(maiorI===4){key='tributos';}
      else if(maiorI===0&&maiorV<0){key='rede';}
      else if(maiorI===2&&maiorV>0){key='demanda';}
      else {key='equilibrado';}
    }
    var D=DIAG[key];

    var vd=$id('rb-vd');
    var somaAviso='';
    if(Math.abs(se-100)>2||Math.abs(sr-100)>2){
      somaAviso=' <b>Atenção às somas:</b> a estimativa soma '+fmt(se,0)+'% e o real soma '+fmt(sr,0)+
        '%. Enquanto as duas não fecharem próximo de cem, o erro por bloco mistura distorção de composição com distorção de escala, e o diagnóstico de viés fica contaminado.';
    }
    vd.className='verdict '+(errTot<=12?'ok':(errTot<=28?'att':'per'));
    vd.innerHTML='<b>'+D.t+'.</b> Erro absoluto total de '+fmt(errTot,0)+
      ' pontos percentuais, com o maior desvio em <b>'+NOMES[maiorI]+'</b> ('+
      (maiorV>0?'+':'')+fmt(maiorV,0)+' p.p.).'+somaAviso;

    $id('rb-out').innerHTML=
      '<div class="ocard"><span class="ok2">O que este padrão significa</span>'+esc(D.sig)+'</div>'+
      '<div class="ocard"><span class="ok2">O efeito prático do viés</span>'+esc(D.efeito)+'</div>'+
      '<div class="ocard"><span class="ok2">Como se corrige</span>'+esc(D.ctrl)+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que ainda falta</span>'+esc(D.falta)+'</div>';
  }

  for(var i=1;i<=6;i++){
    pair('rb-e'+i,'rb-e'+i+'r',calc);
    pair('rb-r'+i,'rb-r'+i+'r',calc);
  }
  calc();
})();

/* ===================== INST·10 — ORDEM DE LEITURA CRONOMETRADA ===================== */
(function(){
  var grid=$id('ol-grid'), panel=$id('ol-panel');
  if(!grid||!panel)return;

  var PASSOS=/* PASSOS: literal elidido, ver dados_do_script.PASSOS (L4472–4518) */;

  var sel=null, feito={};

  function render(){
    grid.innerHTML=PASSOS.map(function(p,i){
      return '<button class="tr-chip'+(sel===p.id?' on':'')+'" data-k="'+p.id+'">'+
        '<span class="y">Passo '+(i+1)+' · '+p.t+'s'+(feito[p.id]?' · feito':'')+'</span>'+esc(p.n)+'</button>';
    }).join('');
    $all('button',grid).forEach(function(b){
      b.addEventListener('click',function(){
        var k=b.getAttribute('data-k');
        if(sel===k){feito[k]=!feito[k];}else{sel=k;}
        render();
      });
    });

    var n=0,tempo=0;
    PASSOS.forEach(function(p){if(feito[p.id]){n++;tempo+=p.t;}});
    $id('ol-cnt').textContent=fmt(n,0)+' de '+PASSOS.length;
    $id('ol-tempo').textContent=fmt(Math.floor(tempo/60),0)+' min '+fmt(tempo%60,0)+' s';

    var est,cls;
    if(n===0){est='Não iniciada';cls='per';}
    else if(n<3){est='Triagem incompleta';cls='per';}
    else if(n<7){est='Leitura parcial';cls='att';}
    else if(n<9){est='Quase completa';cls='att';}
    else {est='Leitura completa';cls='ok';}
    $id('ol-est').textContent=est;

    var vd=$id('ol-vd');
    vd.className='verdict '+cls;
    if(n===0){
      vd.innerHTML='<b>Leitura não iniciada.</b> Clique num passo para ler o detalhe; clique novamente no passo aberto para marcá-lo como executado. A ordem importa mais do que a completude: o erro que custa caro não é a linha esquecida, é a ordem errada, porque ela faz perder o achado que tornaria os demais irrelevantes.';
    } else if(n<3){
      vd.innerHTML='<b>Triagem incompleta — '+fmt(n,0)+' de 9.</b> Os três primeiros passos consomem menos de um minuto e meio somados e respondem à maior parte das perguntas de triagem. Cadastro antes de valores, período antes de comparação: essa é a regra que organiza a sequência inteira.';
    } else if(n<7){
      vd.innerHTML='<b>Leitura parcial — '+fmt(n,0)+' de 9, com '+fmt(Math.floor(tempo/60),0)+' min '+fmt(tempo%60,0)+' s acumulados.</b> As hipóteses já estão levantadas. Falta a camada de verificação: reconciliação de uma linha e composição tributária são o que distingue hipótese de achado.';
    } else if(n<9){
      vd.innerHTML='<b>Quase completa — '+fmt(n,0)+' de 9.</b> Falta o passo que nunca pode ser pulado. O inventário do que falta é o único passo que sempre produz saída, e é ele que determina se o caso avança ou encerra com parecer.';
    } else {
      vd.innerHTML='<b>Leitura completa em '+fmt(Math.floor(tempo/60),0)+' min '+fmt(tempo%60,0)+
        ' s.</b> Os nove passos foram executados dentro do envelope de cinco minutos previsto pelo critério de domínio. O resultado desta leitura alimenta diretamente o roteador de diagnóstico: o que foi observado e o que falta determinam qual dos três vereditos se aplica ao caso.';
    }

    if(!sel){
      panel.innerHTML='<div class="yr">Sequência</div><div class="ti">Escolha um passo</div>'+
        '<div class="bd2">Nove passos, cada um com o que olhar, o critério de parada, o achado que torna os demais irrelevantes e o que registrar. Clicar abre o detalhe; clicar de novo marca como executado.</div>';
      return;
    }
    var P=null,idx=0;
    for(var i=0;i<PASSOS.length;i++){if(PASSOS[i].id===sel){P=PASSOS[i];idx=i+1;}}
    if(!P)return;
    panel.innerHTML='<div class="yr">Passo '+idx+' · '+P.t+' segundos'+(feito[P.id]?' · executado':'')+'</div>'+
      '<div class="ti">'+esc(P.n)+'</div>'+
      '<div class="out" style="margin-top:6px">'+
      '<div class="ocard"><span class="ok2">O que se olha</span>'+esc(P.olh)+'</div>'+
      '<div class="ocard"><span class="ok2">Critério de parada</span>'+esc(P.par)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">O que torna os demais irrelevantes</span>'+P.irr+'</div>'+
      '<div class="ocard gd2"><span class="ok2">O que registrar</span>'+esc(P.reg)+'</div>'+
      '</div>';
  }
  render();
})();

/* ===================== INST·11 — ROTEADOR DE DIAGNÓSTICO ===================== */
(function(){
  var vd=$id('rt-vd'), out=$id('rt-out');
  if(!vd||!out)return;

  var ACHADO=/* ACHADO: literal elidido, ver dados_do_script.ACHADO (L4588–4609) */;

  function score(h,m,p){
    var s=0;
    if(h==='doze')s+=3; else if(h==='seis')s+=1;
    if(m==='sim')s+=3; else if(m==='parcial')s+=1;
    if(p==='estavel')s+=2; else if(p==='mudanca')s+=1;
    return s;
  }

  function render(){
    var h=segVal('rt-hist','data-h')||'uma';
    var m=segVal('rt-mm','data-m')||'nao';
    var p=segVal('rt-plano','data-p')||'nao';
    var a=segVal('rt-ach','data-a')||'enq';
    var A=ACHADO[a];
    var s=score(h,m,p);

    var falta=[];
    if(h==='uma')falta.push('doze meses de faturas consecutivas, com refaturamentos e ajustes preservados e vinculados ao período de origem');
    else if(h==='seis')falta.push('os meses restantes para completar um ciclo anual, sem o qual sazonalidade e paradas programadas ficam fora da janela observada');
    if(m==='nao')falta.push('a memória de massa por intervalo, que é o único registro capaz de mostrar quando e por quanto tempo cada pico ocorreu');
    else if(m==='parcial')falta.push('a complementação da memória de massa nos períodos ausentes, com verificação de quebra de série por troca de medidor');
    if(p==='nao')falta.push('o plano de produção com expansões, paradas programadas e mudanças de turno previstas');
    else if(p==='mudanca')falta.push('o cronograma detalhado da mudança prevista, com potência e simultaneidade das cargas novas');
    falta.push('as tarifas homologadas da concessionária nos períodos analisados, com número e data da resolução de referência');
    if(a==='fp')falta.push('medição de qualidade de energia, se houver carga não linear relevante na instalação');
    if(a==='amb')falta.push('o custo entregue consolidado dos dois lados, no mesmo período e na mesma unidade de medida');

    var cls,titulo,corpo;
    if(a==='nada'&&s>=6){
      cls='ok'; titulo='Não vale investigar nas condições informadas';
      corpo='Com histórico e medição disponíveis e nenhum achado observado na leitura, o material sustenta um <b>parecer de adequação</b>. Essa é a saída mais difícil de emitir e a mais valiosa comercialmente: quem só sabe encontrar problema não tem como ser acreditado quando encontra um. Registre a base sobre a qual a adequação foi afirmada e a data — adequação é afirmação sobre um momento, não sobre o futuro.';
    } else if(s>=6){
      cls='att'; titulo='Vale investigar';
      corpo='O material disponível sustenta o avanço para análise completa sobre o achado <b>'+esc(A.n)+
        '</b>. Há histórico e medição suficientes para distinguir padrão estrutural de evento isolado, que é a condição mínima para qualquer conclusão dimensional. A investigação ainda pode terminar sem achado material, e isso continua sendo entrega.';
    } else if(s<=1&&a!=='nada'){
      cls='per'; titulo='Não é possível concluir com o que foi informado';
      corpo='O achado <b>'+esc(A.n)+'</b> foi observado, mas o material disponível não sustenta conclusão de nenhuma natureza dimensional. '+
        esc(A.semDados)+' Esta é a saída mais frequente de uma varredura honesta, e emiti-la não é falha de análise — é o resultado da análise.';
    } else if(s<=1&&a==='nada'){
      cls='per'; titulo='Não é possível concluir com o que foi informado';
      corpo='Nenhum achado foi observado, mas com uma fatura isolada e sem medição por intervalo <b>a ausência de achado não é prova de adequação</b>. A distinção importa: dizer que nada foi identificado com o material disponível é diferente de dizer que está adequado. A segunda afirmação exige a mesma evidência que um achado positivo exigiria.';
    } else {
      cls='att'; titulo='Não é possível concluir — investigação parcial viável';
      corpo='O material sustenta caracterizar o achado <b>'+esc(A.n)+
        '</b> e levantar hipótese, mas não sustenta conclusão dimensional. '+esc(A.semDados)+
        ' O caminho correto é entregar o que já é afirmável e a lista do que falta, em vez de esperar todos os dados para dizer qualquer coisa.';
    }

    vd.className='verdict '+cls;
    vd.innerHTML='<b>'+titulo+'.</b> '+corpo;

    out.innerHTML=
      '<div class="ocard"><span class="ok2">O que este achado exige para concluir</span>'+esc(A.exige)+'</div>'+
      '<div class="ocard"><span class="ok2">O que já é afirmável com o disponível</span>'+esc(A.minimo)+'</div>'+
      '<div class="ocard rd2"><span class="ok2">Lista do que falta</span>'+
        falta.map(function(f){return '· '+esc(f);}).join('<br>')+'</div>'+
      '<div class="ocard gd2"><span class="ok2">A resposta a "quanto eu economizo"</span>Uma pergunta de volta e uma lista, nunca um número. A pergunta: quantos meses de histórico existem e existe medição por intervalo? A lista é a do campo anterior. Um percentual aproximado dado sem dados vira compromisso na cabeça de quem ouviu — e quando os dados chegam e o número real é outro, o que se perde não é o cliente, é a autoridade.</div>';
  }

  segBind('rt-hist',render);
  segBind('rt-mm',render);
  segBind('rt-plano',render);
  segBind('rt-ach',render);
  render();
})();
